    @else
        {{-- COURSES STATE --}}
        <div class="px-6 pt-4 pb-2">
            <h1 class="text-5xl md:text-6xl font-bold text-gray-900">
                Welcome, {{ Auth::user()->name ? explode(' ', Auth::user()->name)[0] : 'there' }}
            </h1>
        </div>

        <div class="flex flex-col xl:flex-row gap-6 px-6 pb-6" x-data="{ view: 'list', currentFilter: '{{ ucfirst($filter) }}' }">
            {{-- LEFT COLUMN - Courses --}}
            <div class="flex-1">
                {{-- Header Row --}}
                <div class="flex items-center justify-between mb-4">
                    <h2 class="text-lg font-bold text-gray-900">Courses You&rsquo;re Taking</h2>

                    <div class="flex items-center gap-3">
                        {{-- Generate Course Button (AI-styled) --}}
                        <a href="{{ route('courses.create') }}"
                           class="ai-button text-white text-sm font-semibold px-4 py-2 rounded-xl flex items-center gap-2 no-underline">
                            <svg class="w-4 h-4" viewBox="0 0 24 24" fill="none">
                                <path d="M12 2L14.09 8.26L20 9.27L15.55 13.97L16.91 20L12 16.9L7.09 20L8.45 13.97L4 9.27L9.91 8.26L12 2Z"
                                      fill="white" opacity="0.9"/>
                                <path d="M5 3L5.5 5L7 5.5L5.5 6L5 8L4.5 6L3 5.5L4.5 5L5 3Z"
                                      fill="white" opacity="0.7"/>
                            </svg>
                            <span class="hidden sm:inline">Generate Course</span>
                        </a>
                        {{-- List View Toggle --}}
                        <button @click="view = 'list'"
                                class="p-1.5 rounded-md transition-colors"
                                :class="view === 'list' ? 'bg-gray-100 text-gray-900' : 'text-gray-400 hover:text-gray-600'">
                            <svg class="w-5 h-5" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
                                <line x1="3" y1="6" x2="21" y2="6"/>
                                <line x1="3" y1="12" x2="21" y2="12"/>
                                <line x1="3" y1="18" x2="21" y2="18"/>
                            </svg>
                        </button>

                        {{-- Grid View Toggle --}}
                        <button @click="view = 'grid'"
                                class="p-1.5 rounded-md transition-colors"
                                :class="view === 'grid' ? 'bg-gray-100 text-gray-900' : 'text-gray-400 hover:text-gray-600'">
                            <svg class="w-5 h-5" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
                                <rect x="3" y="3" width="8" height="8" rx="1"/>
                                <rect x="13" y="3" width="8" height="8" rx="1"/>
                                <rect x="3" y="13" width="8" height="8" rx="1"/>
                                <rect x="13" y="13" width="8" height="8" rx="1"/>
                            </svg>
                        </button>

                        {{-- Filter Dropdown --}}
                        <div x-data="{ filterOpen: false }" class="relative">
                            <button @click="filterOpen = !filterOpen"
                                    class="flex items-center gap-1.5 text-sm font-medium text-gray-700 border border-gray-200 rounded-lg px-3 py-1.5 hover:bg-gray-50 transition-colors">
                                <span x-text="currentFilter"></span>
                                <svg class="w-3.5 h-3.5 transition-transform" :class="filterOpen ? 'rotate-180' : ''" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
                                    <polyline points="6 9 12 15 18 9"/>
                                </svg>
                            </button>

                            <div x-show="filterOpen"
                                 x-transition
                                 @click.away="filterOpen = false"
                                 class="absolute right-0 mt-1 w-36 bg-white rounded-lg shadow-lg border border-gray-100 py-1 z-20">
                                @foreach(['Active', 'Completed', 'All'] as $filterOption)
                                    <a href="{{ route('my-courses', ['filter' => strtolower($filterOption)]) }}"
                                       class="block w-full text-left px-4 py-2 text-sm text-gray-600 hover:bg-purple-50 hover:text-purple-600 transition-colors {{ $filter === strtolower($filterOption) ? 'text-purple-600 font-medium bg-purple-50' : '' }}">
                                        {{ $filterOption }}
                                    </a>
